# pyright: basic
# This file is mostly GearPiece data declarations plus a few module-level
# validation loops. It is checked at "basic" rather than the project's "strict"
# level: strict would emit thousands of reportUnknown* diagnostics on the data
# without catching real bugs. Consumers treat the exported lists as
# list[GearPiece] (see wsdist_types).
'''
This file contains a list of all gear to be considered by the application.
name is the item name as seen in-game. name is used to pull the correct item id (taken from Windower resource files) and extract item icons (downloaded from BG Wiki as 32x32 px PNG)
name2 is the same as name, but it includes augment paths. name2 is only used to distinguish between augment paths/ranks. All augmented items should be given a name2 specifying their path/rank.
skill_type is on weapons and describes the combat skill associated with the weapon (katana, club, sword, etc).
type is used exclusively for main, sub, ranged, and ammo slots. type is used for the code to distinguish between different item types and prevent equipping impossible combinations (Dagger+Grip, Gun+Arrow, Staff+Shield, Bow+Bullet, etc). The options are "weapon", "grip", "ranged", "ammo", "shuriken", "throwing". 
    Shuriken is a special case of "throwing" that enables Daken for Ninja TPing.

Author: Kastra (Asura server)
'''

# GearPiece.jobs lists the jobs that can wear an item. This is used to quickly gather all pieces of gear that a job can wear to be tested. (if "nin" in jobs). Future work.
from wsdist_types import GearPiece

all_jobs = ["war", "mnk", "whm", "blm", "rdm", "thf", "pld", "drk", "bst", "brd", "rng", "smn", "sam", "nin", "drg", "blu", "cor", "pup", "dnc", "sch", "geo", "run"]
base_parameters = ["STR", "DEX", "AGI", "VIT", "INT", "MND", "CHR"]


# Convert items.lua file into a reduced weapons and armor only .txt file:
# sed "s/",ja\=.*category=/;/g" items.lua | sed "s/\,flags=.*//g" | sed "s/^.*id=//g" | sed "s/,en=\"/;/" | sed "s/\"//g" | sed "s/Weapon\,da.*/Weapon/g" | awk -F";" "{if($3=="Armor" || $3=="Weapon") print $1";"$2}" > item_list.txt

Empty: GearPiece = GearPiece(name="Empty", type="None", skill_type="None", jobs=all_jobs)

